Oséias 11 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde Deus diz que chamou seu filho?","o":["Da Assíria","Da Babilônia","Do Egito","De Canaã"],"c":2,"v":1,"e":"No versículo 1, Deus diz: \"do Egito chamei meu filho\"."},
 {"t":"multipla","p":"A quem o povo sacrificava enquanto se afastava de Deus?","o":["A baalins","Ao bezerro de ouro","A Moloque","A Dagom"],"c":0,"v":2,"e":"O versículo 2 diz que \"sacrificavam a baalins e queimavam incenso às imagens esculpidas\"."},
 {"t":"multipla","p":"A quem Deus diz que ensinou a andar?","o":["Judá","Efraim","Benjamim","Manassés"],"c":1,"v":3,"e":"No versículo 3, Deus diz: \"ensinei a andar a Efraim\"."},
 {"t":"multipla","p":"Segundo o capítulo, quem seria o rei do povo por se recusar a se converter?","o":["O Egito","A Babilônia","A Assíria","Judá"],"c":2,"v":5,"e":"O versículo 5 diz que \"a Assíria será seu rei, porque se recusam a se converter\"."},
 {"t":"multipla","p":"Com que cidades Deus pergunta como poderia tratar Efraim?","o":["Sodoma e Gomorra","Admá e Zeboiim","Jericó e Ai","Tiro e Sidom"],"c":1,"v":8,"e":"No versículo 8, Deus pergunta: \"Como eu poderia tratá-lo como Admá? Como eu poderia fazê-lo como Zeboiim?\"."},
 {"t":"cv","p":"Deus afirma que executará o furor da sua ira e destruirá Efraim.","c":false,"v":9,"e":"No versículo 9, Deus diz o contrário: \"Não executarei o furor da minha ira, nem tornarei para destruir Efraim\"."},
 {"t":"cv","p":"O capítulo diz que o Senhor rugirá como um leão.","c":true,"v":10,"e":"O versículo 10 diz que o Senhor \"rugirá como um leão\" e que os filhos do Ocidente tremerão."},
 {"t":"cv","p":"Segundo o capítulo, Judá também cercou Deus com mentiras, assim como Efraim.","c":false,"v":12,"e":"O versículo 12 diz que Efraim cercou Deus com mentiras, mas que \"Judá ainda reina com Deus e é fiel ao Santo\"."}
]}

Oséias 10 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No início do capítulo, Israel é comparado a quê?","o":["Uma figueira sem fruto","Uma vide luxuriante","Uma oliveira verde","Um cedro do Líbano"],"c":1,"v":1,"e":"No versículo 1, Israel é uma vide luxuriante que dá fruto para si mesmo."},
 {"t":"multipla","p":"Por que o povo dirá \"Não temos rei\"?","o":["Porque o rei fugiu para o Egito","Porque o rei morreu na batalha","Porque não temeram ao Senhor","Porque Judá tomou o trono"],"c":2,"v":3,"e":"No versículo 3, o povo diz que não tem rei porque não temeu ao Senhor."},
 {"t":"multipla","p":"Para onde será levado o bezerro de Bete-Áven?","o":["Para a Assíria, como presente ao rei Jareb","Para o Egito, como tributo ao faraó","Para Jerusalém, para ser destruído","Para Babilônia, como despojo de guerra"],"c":0,"v":6,"e":"O versículo 6 diz que o bezerro será levado à Assíria como presente ao rei Jareb."},
 {"t":"multipla","p":"O que dirão aos montes quando os altares forem destruídos?","o":["\"Protejam-nos!\"","\"Escondam nossos ídolos!\"","\"Abram caminho!\"","\"Cubram-nos!\""],"c":3,"v":8,"e":"No versículo 8, dirão aos montes \"Cubram-nos!\" e aos outeiros \"Caiam sobre nós!\"."},
 {"t":"multipla","p":"Efraim é comparado a qual animal?","o":["Um jumento teimoso","Uma bezerra domada que gosta de trilhar","Um leão novo","Uma pomba ingênua"],"c":1,"v":11,"e":"O versículo 11 diz que Efraim é uma bezerra domada que gosta de trilhar."},
 {"t":"cv","p":"O capítulo diz que Israel pecou desde os dias de Gibeá.","c":true,"v":9,"e":"O versículo 9 diz: \"Desde os dias de Gibeá, tu pecaste, ó Israel\"."},
 {"t":"cv","p":"O capítulo diz que o povo semeou justiça e colheu bondade.","c":false,"v":13,"e":"O versículo 13 diz que semearam malícia, colheram perversidade e comeram o fruto da mentira."},
 {"t":"cv","p":"No fim do capítulo, o rei de Israel será totalmente destruído, como a alva passa.","c":true,"v":15,"e":"O versículo 15 diz que, como a alva passa, assim o rei de Israel será totalmente destruído."}
]}

Oséias 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Israel não deveria se alegrar nem exultar como os povos?","o":["Porque, pela infidelidade, abandonou o seu Deus","Porque perdeu uma guerra contra o Egito","Porque o rei se recusou a ouvir o profeta","Porque deixou de celebrar a Páscoa"],"c":0,"v":1,"e":"No versículo 1, Israel é avisado a não se alegrar porque, pela sua infidelidade, abandonou o seu Deus."},
 {"t":"multipla","p":"Para onde o texto diz que Efraim retornará?","o":["Babilônia","Egito","Moabe","Edom"],"c":1,"v":3,"e":"O versículo 3 diz que Efraim não permanecerá na terra do Senhor, mas retornará ao Egito."},
 {"t":"multipla","p":"Que cidade os sepultará, segundo o capítulo?","o":["Nínive","Samaria","Mênfis","Damasco"],"c":2,"v":6,"e":"O versículo 6 diz que o Egito os ceifará e Mênfis os sepultará."},
 {"t":"multipla","p":"Corromperam-se profundamente como nos dias de quê?","o":["De Sodoma","De Babel","De Gibeá","De Noé"],"c":2,"v":9,"e":"O versículo 9 diz que se corromperam profundamente como nos dias de Gibeá."},
 {"t":"multipla","p":"Para onde foram os pais de Israel, consagrando-se à idolatria?","o":["Betel","Baal-Peor","Gilgal","Dã"],"c":1,"v":10,"e":"O versículo 10 conta que foram para Baal-Peor e se consagraram à vergonhosa idolatria."},
 {"t":"cv","p":"Deus diz que achou Israel como uvas no deserto.","c":true,"v":10,"e":"O versículo 10 começa com: 'Achei Israel como uvas no deserto'."},
 {"t":"cv","p":"O texto diz que Efraim está ferido, suas raízes secaram e não dará frutos.","c":true,"v":16,"e":"O versículo 16 afirma que Efraim está ferido, suas raízes secaram e não dará frutos."},
 {"t":"cv","p":"O capítulo termina dizendo que Israel será reunido de volta em sua terra.","c":false,"v":17,"e":"O versículo 17 diz o contrário: por não terem ouvido a Deus, andarão errantes entre as nações."}
]}

Oséias 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Efraim era exaltado em Israel, mas morreu ao se fazer culpado em quem?","o":["Baal","Moloque","Dagom","Astarote"],"c":0,"v":1,"e":"O versículo 1 diz que Efraim, ao se fazer culpado em Baal, morreu."},
 {"t":"multipla","p":"Segundo o que diziam, os homens até beijam o quê?","o":["Bezerros","Serpentes de bronze","Estátuas de ouro","Altares de pedra"],"c":0,"v":2,"e":"No versículo 2 eles dizem: \"Sacrificai a eles; os homens até beijam bezerros!\""},
 {"t":"multipla","p":"Por causa da idolatria, com o que o povo é comparado?","o":["Com o orvalho que cedo se dissipa","Com a rocha firme","Com o cedro do Líbano","Com o rio que não seca"],"c":0,"v":3,"e":"O versículo 3 os compara à nuvem da manhã, ao orvalho que cedo se dissipa, à palha e à fumaça."},
 {"t":"multipla","p":"O que aconteceu quando o povo tinha pasto e se fartou?","o":["O coração se ensoberbeceu e eles se esqueceram de Deus","Eles ofereceram sacrifícios de gratidão","Eles repartiram com os pobres","Eles voltaram para o Egito"],"c":0,"v":6,"e":"O versículo 6 diz que se fartaram, o coração se ensoberbeceu e por isso se esqueceram de Deus."},
 {"t":"multipla","p":"Deus diz que atacará o povo como qual animal?","o":["Uma ursa roubada de seus filhotes","Um lobo faminto","Uma águia sobre a presa","Uma serpente no caminho"],"c":0,"v":8,"e":"O versículo 8 diz: \"Como uma ursa que foi roubada de seus filhotes, eu os atacarei\"."},
 {"t":"cv","p":"Deus diz que deu um rei a Israel na sua ira e que o tirará no seu furor.","c":true,"v":11,"e":"O versículo 11 diz: \"Eu te dei um rei na minha ira, e eu o tirarei no meu furor\"."},
 {"t":"cv","p":"O vento que vem secar a raiz de Efraim é o vento norte, que sobe do mar.","c":false,"v":15,"e":"O versículo 15 fala do vento leste, o vento do Senhor, subindo do deserto."},
 {"t":"cv","p":"Samaria cairá à espada porque se rebelou contra o seu Deus.","c":true,"v":16,"e":"O versículo 16 diz que Samaria se rebelou contra o seu Deus e cairá à espada."}
]}

Oséias 14 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Israel está caído, segundo o chamado inicial?","o":["Por causa dos seus pecados","Por causa da fome na terra","Por causa da guerra contra a Assíria","Por causa dos falsos profetas"],"c":0,"v":1,"e":"O versículo 1 diz que Israel está caído por causa dos seus pecados."},
 {"t":"multipla","p":"Em vez de novilhos, o que o povo diz que oferecerá ao Senhor?","o":["As primícias da colheita","O sacrifício dos seus lábios","Cordeiros sem defeito","Incenso no altar"],"c":1,"v":2,"e":"No versículo 2 o povo promete oferecer o sacrifício dos lábios em vez de novilhos."},
 {"t":"multipla","p":"Que nação o povo reconhece que não o salvará?","o":["Egito","Babilônia","Assíria","Moabe"],"c":2,"v":3,"e":"O versículo 3 diz: \"Não nos salvará a Assíria\"."},
 {"t":"multipla","p":"O que o Senhor promete sarar?","o":["As feridas da guerra","A terra seca","Os doentes do povo","A infidelidade deles"],"c":3,"v":4,"e":"No versículo 4 o Senhor diz: \"Eu sararei a sua infidelidade\"."},
 {"t":"multipla","p":"Com o que o Senhor diz que será para Israel?","o":["Como orvalho","Como uma rocha","Como chuva forte","Como o sol"],"c":0,"v":5,"e":"O versículo 5 diz: \"Serei para Israel como orvalho\"."},
 {"t":"cv","p":"A glória de Israel será como a da oliveira.","c":true,"v":6,"e":"O versículo 6 diz que a glória de Israel será como a da oliveira."},
 {"t":"cv","p":"Efraim dirá que quer continuar servindo aos ídolos.","c":false,"v":8,"e":"No versículo 8 Efraim diz o contrário: \"Que mais tenho eu com os ídolos?\"."},
 {"t":"cv","p":"Os transgressores caminharão com firmeza nos caminhos do Senhor.","c":false,"v":9,"e":"O versículo 9 diz que os justos caminharão nos caminhos do Senhor, mas os transgressores neles tropeçarão."}
]}

Oséias 12 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Com quem Efraim faz aliança?","o":["Com a Assíria","Com a Babilônia","Com o Egito","Com a Síria"],"c":0,"v":1,"e":"No começo do capítulo se diz que Efraim faz aliança com a Assíria, e o azeite é levado ao Egito."},
 {"t":"multipla","p":"O que Jacó fez ainda no ventre?","o":["Lutou com o anjo","Agarrou o calcanhar de seu irmão","Chorou e pediu misericórdia","Recebeu o nome de Israel"],"c":1,"v":3,"e":"O capítulo diz que no ventre ele agarrou o calcanhar de seu irmão e, na força, lutou com Deus."},
 {"t":"multipla","p":"Onde Jacó encontrou Deus?","o":["Em Gilgal","Em Gileade","Em Betel","No Egito"],"c":2,"v":4,"e":"Depois de lutar com o anjo e prevalecer, o texto diz que em Betel ele encontrou Deus."},
 {"t":"multipla","p":"O que há na mão do mercador?","o":["Uma espada","Ouro e prata","Uma vara de pastor","Uma balança enganosa"],"c":3,"v":7,"e":"O texto diz que na mão do mercador há uma balança enganosa e que ele ama a opressão."},
 {"t":"multipla","p":"O que Efraim diz de si mesmo?","o":["Que enriqueceu e não há pecado nele","Que está pobre e arrependido","Que serviu ao Senhor fielmente","Que temia a Assíria"],"c":0,"v":8,"e":"Efraim diz que se enriqueceu e adquiriu grandes bens e que não encontrarão nele iniquidade alguma."},
 {"t":"cv","p":"Em Gilgal sacrificam bois.","c":true,"v":11,"e":"Depois de perguntar sobre Gileade, o texto diz que em Gilgal sacrificam bois."},
 {"t":"cv","p":"Jacó fugiu para a terra do Egito.","c":false,"v":12,"e":"O capítulo diz que Jacó fugiu para a terra da Síria, onde serviu por uma mulher."},
 {"t":"cv","p":"O capítulo termina dizendo que o Senhor perdoará Efraim pelo sangue que ele derramou.","c":false,"v":14,"e":"No final se diz que o Senhor deixará cair sobre Efraim o sangue que ele mesmo derramou e trará sobre ele a sua vergonha."}
]}
